index 8adb4969baec..5f101a20a20a 100644
--- a/arch/arm64/boot/dts/qcom/msm8998-mtp.dtsi
+++ b/arch/arm64/boot/dts/qcom/msm8998-mtp.dtsi
@@ -41,6 +41,66 @@ &blsp2_uart1 {
 	status = "okay";
 };

+&etf {
+	status = "okay";
+};
